/**
 * Create a vertical gradient texture with hard seam at 50%
 * Colors interpolate between stops; seam line is bright at midpoint
 */
function createGradientTexture(stops) {
  const texWidth = 512;
  const texHeight = 320;
  const data = new Uint8Array(texWidth * texHeight * 4);
  const seamRow = Math.floor(texHeight * 0.5);
  const seamThickness = 2;

  for (let y = 0; y < texHeight; y++) {
    const t = y / texHeight;
    let r, g, b;

    // Hard seam line at 50%
    if (Math.abs(y - seamRow) < seamThickness) {
      r = g = b = 255; // bright white seam
    } else {
      const color = interpolateGradient(stops, t);
      r = color.r;
      g = color.g;
      b = color.b;
    }

    // Fill entire row
    for (let x = 0; x < texWidth; x++) {
      const idx = (y * texWidth + x) * 4;
      data[idx] = r;
      data[idx + 1] = g;
      data[idx + 2] = b;
      data[idx + 3] = 255;
    }
  }

  const texture = new THREE.DataTexture(data, texWidth, texHeight, THREE.RGBAFormat);
  texture.needsUpdate = true;
  return texture;
}

/**
 * Interpolate gradient color at position t [0,1]
 */
function interpolateGradient(stops, t) {
  for (let i = 0; i < stops.length - 1; i++) {
    const s0 = stops[i];
    const s1 = stops[i + 1];

    if (t >= s0.at && t <= s1.at) {
      const segmentT = (t - s0.at) / (s1.at - s0.at);
      return lerpColor(s0.hex, s1.hex, segmentT);
    }
  }

  // Fallback to last stop
  return hexToRgb(stops[stops.length - 1].hex);
}

/**
 * Linear interpolation between two hex colors
 */
function lerpColor(hex1, hex2, t) {
  const c1 = hexToRgb(hex1);
  const c2 = hexToRgb(hex2);

  return {
    r: Math.round(c1.r + (c2.r - c1.r) * t),
    g: Math.round(c1.g + (c2.g - c1.g) * t),
    b: Math.round(c1.b + (c2.b - c1.b) * t)
  };
}

/**
 * Parse hex color to RGB object
 */
function hexToRgb(hex) {
  const match = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);

  if (!match) {
    return { r: 255, g: 255, b: 255 };
  }

  return {
    r: parseInt(match[1], 16),
    g: parseInt(match[2], 16),
    b: parseInt(match[3], 16)
  };
}
